import express from 'express';
import pg from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: true, ca: readFileSync('/etc/ssl/rds-ca.pem') },
  max: 20
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing tenant token' });
  // In production this verifies JWT signature - simplified here
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tid;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'invalid token' });
  }
}

app.use('/api', extractTenant);

// Vulnerable endpoint: dynamic column ordering with unsanitized input
app.get('/api/reports/export', async (req, res) => {
  const { start_date, end_date, group_by, metric } = req.query;

  // These are parameterized - safe
  const dateFilter = 'created_at BETWEEN $1 AND $2';
  const tenantFilter = 'tenant_id = $3';

  // Allowlist for group_by
  const allowedGroups = ['department', 'region', 'product_line', 'quarter'];
  const safeGroupBy = allowedGroups.includes(group_by) ? group_by : 'department';

  // VULNERABLE: metric parameter is used in aggregate expression without sanitization
  // Developer assumed it would be one of: revenue, cost, headcount, margin
  // But it's directly interpolated into SQL
  const query = `
    SELECT ${safeGroupBy}, 
           SUM(${metric}) as total,
           COUNT(*) as record_count,
           AVG(${metric}) as average
    FROM financial_reports 
    WHERE ${tenantFilter} AND ${dateFilter}
    GROUP BY ${safeGroupBy}
    ORDER BY total DESC
    LIMIT 100`;

  try {
    const result = await pool.query(query, [start_date, end_date, req.tenantId]);

    // Audit logging (parameterized - safe)
    await pool.query(
      'INSERT INTO audit_log (user_id, tenant_id, action, params, ts) VALUES ($1, $2, $3, $4, NOW())',
      [req.userId, req.tenantId, 'report_export', JSON.stringify({ start_date, end_date, group_by, metric })]
    );

    res.json({ data: result.rows, generated_at: new Date().toISOString() });
  } catch (e) {
    console.error('Report query failed:', e.message);
    res.status(500).json({ error: 'report generation failed' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch (e) {
    res.status(503).json({ status: 'unhealthy' });
